import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    static Map<String, Integer> allCache = new HashMap<>();
    static Map<String, Integer> limitCache = new HashMap<>();
    static int n = 0, m = 0;

    static int computeAll(int start, int end) {
        if (start == end) {
            return 1;
        }
        String key = start + "," + end;
        if (allCache.containsKey(key)) {
            return allCache.get(key);
        }
        int result = 0;
        result += computeAll(start + 1, end);
        result += computeAll(start, end - 1);
        for (int i = start + 1; i < end; i++) {
            result += computeAll(start, i - 1) * computeAll(i + 1, end);
        }
        allCache.put(key, result);
        return result;
    }

    static int computeLimit(int start, int end, int depth) {
        String key = start + "," + end + "," + depth;
        if (start == end) {
            return (depth < m) ? 1 : 0;
        }
        if (limitCache.containsKey(key)) {
            return limitCache.get(key);
        }
        int result = 0;
        result += computeLimit(start + 1, end, depth + 1);
        result += computeLimit(start, end - 1, depth + 1);
        for (int i = start + 1; i < end; i++) {
            result += computeLimit(start, i - 1, depth + 1) * computeLimit(i + 1, end, depth + 1);
        }
        limitCache.put(key, result);
        return result;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        n = scanner.nextInt();
        m = scanner.nextInt();
        int total = computeAll(1, n) - computeLimit(1, n, 1);
        System.out.println(total);
        scanner.close();
    }
}
